			Predicate n4 = cb.equal(b.get("sectionId"), req.getSectionId());
			Predicate n5 = cb.equal(b.get("coverId"), req.getCoverId());
			query.where(n1, n2, n3,n4,n5,n6,n7).orderBy(orderList);
			
			// Get Result
